#include <vector>
#include <omp.h>

void negateOddsAndHalveEvens(std::vector<int> &x) {
    const std::size_t n = x.size();

    #pragma omp parallel for default(none) shared(x, n)
    for (std::size_t i = 0; i < n; ++i) {
        if ((x[i] & 1) != 0) {
            x[i] = -x[i];
        } else {
            x[i] /= 2;
        }
    }
}
